import{_ as e,a,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const p=JSON.parse('{"title":"Tax Categories","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/settings/tax-categories/index.md","filePath":"api/graphql-api/admin/settings/tax-categories/index.md","lastUpdated":1784902076000}'),d={name:"api/graphql-api/admin/settings/tax-categories/index.md"};function i(n,t,s,c,h,g){return o(),a("div",null,t[0]||(t[0]=[r('<h1 id="tax-categories" tabindex="-1">Tax Categories <a class="header-anchor" href="#tax-categories" aria-label="Permalink to &quot;Tax Categories&quot;">​</a></h1><p>A <strong>tax category</strong> is a named group of tax rates. It is the bridge between your products and the individual tax rates that determine how much tax they&#39;re charged: each product is assigned a tax category, and the category carries the set of tax rates that apply. This menu mirrors the admin <strong>Settings → Taxes → Tax Categories</strong> screen.</p><h2 id="how-tax-categories-fit-together" tabindex="-1">How tax categories fit together <a class="header-anchor" href="#how-tax-categories-fit-together" aria-label="Permalink to &quot;How tax categories fit together&quot;">​</a></h2><p>Tax rates (under <a href="./../tax-rates/">Settings → Taxes → Tax Rates</a>) are the individual rate rows — each one is a percentage that applies under certain conditions (country, state, zip, etc.). A tax category bundles one or more of those rates under a single name. You then assign the category to a product, and at checkout the right rate from the category is applied to that product.</p><p>So the relationship is: <strong>products → tax category → tax rates</strong>. Editing a category changes which rates apply to every product that uses it.</p><h2 id="fields" tabindex="-1">Fields <a class="header-anchor" href="#fields" aria-label="Permalink to &quot;Fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>code</code></td><td>A unique machine code identifying the category (used internally and when assigning the category to products).</td></tr><tr><td><code>name</code></td><td>The human-readable display name shown in the admin.</td></tr><tr><td><code>description</code></td><td>A free-text description of what the category is for.</td></tr><tr><td><code>taxRates</code></td><td>The tax rates attached to this category, exposed as a <strong>field-selectable connection</strong> — select <code>taxRates { edges { node { _id identifier taxRate } } }</code>. Each node carries the rate&#39;s <code>_id</code>, <code>identifier</code>, and <code>taxRate</code> (the percentage). This connection is <strong>detail-only</strong> — it resolves on the single-category query but has empty <code>edges</code> on the listing.</td></tr></tbody></table><h2 id="creating-updating-and-deleting" tabindex="-1">Creating, updating, and deleting <a class="header-anchor" href="#creating-updating-and-deleting" aria-label="Permalink to &quot;Creating, updating, and deleting&quot;">​</a></h2><ul><li><strong>Create</strong> — supply <code>code</code>, <code>name</code>, <code>description</code>, and a non-empty <code>taxrates</code> list of existing tax-rate ids. A tax category cannot be created without at least one rate attached.</li><li><strong>Update</strong> — re-syncs the category. The <code>taxrates</code> list you send <strong>replaces</strong> the current set (rates not in the list are detached, new ones are attached). It is required and must be non-empty.</li><li><strong>Delete</strong> — removes the category, but only if it has <strong>no tax rates attached</strong>. A category that still has rates attached is refused. Because both create and update require a non-empty <code>taxrates</code> list, a category becomes deletable only once it has no attached rates.</li></ul><div class="warning custom-block"><p class="custom-block-title">Delete guard</p><p>You can&#39;t delete a tax category that still has tax rates attached — the request is refused. The category must be empty of rates before it can be removed.</p></div><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="./list.html">List tax categories</a></td><td><code>adminSettingsTaxCategories</code> query</td></tr><tr><td><a href="./detail.html">Get a tax category</a></td><td><code>adminSettingsTaxCategory(id:)</code> query</td></tr><tr><td><a href="./create.html">Create a tax category</a></td><td><code>createAdminSettingsTaxCategory</code> mutation</td></tr><tr><td><a href="./update.html">Update a tax category</a></td><td><code>updateAdminSettingsTaxCategory</code> mutation</td></tr><tr><td><a href="./delete.html">Delete a tax category</a></td><td><code>deleteAdminSettingsTaxCategory</code> mutation</td></tr></tbody></table><p>Permissions: <code>settings.taxes.tax_categories.create</code> / <code>.edit</code> / <code>.delete</code>.</p><p>All operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',14)]))}const u=e(d,[["render",i]]);export{p as __pageData,u as default};
